def evolved_p93(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # Formula: x[i] = i XOR (i >> 1) -- binary-reflected Gray code.
    # Precompute the exact permutation in Python (deterministic), load as constant.
    vals = [k ^ (k >> 1) for k in range(N)]
    return torch.tensor(vals, device=x.device).to(x.dtype)
